    class FilterSpark : FrameworkElement
    {
        public IList<FilterDay> Days;
        public int Mode;
        public FilterSpark(){Height=145;IsHitTestVisible=false;}
        protected override void OnRender(DrawingContext d)
        {
            double w=ActualWidth,h=ActualHeight-24;if(w<1)return;var monday=DateTime.Today.AddDays(-((int)DateTime.Today.DayOfWeek+6)%7);
            var values=Enumerable.Range(0,7).Select(i=>Days==null?0:Days.Where(v=>v.Day==monday.AddDays(i).ToString("yyyy-MM-dd")).Sum(v=>Mode==1?v.Malicious:Mode==2?v.ProtectedSeconds:Mode==3?0:v.Shorts+v.Adults+v.Ads)).ToArray();int max=Math.Max(1,values.Max());
            for(int n=0;n<3;n++)d.DrawLine(new Pen(AtlasPalette.Brush("#857492",.14),.6),new Point(0,8+n*(h-8)/2),new Point(w,8+n*(h-8)/2));
            for(int i=0;i<7;i++){double x=18+i*(w-30)/7,bar=(h-14)*(values[i]/(double)max);d.DrawRoundedRectangle(AtlasPalette.Brush("#827590",.13),null,new Rect(x,10,7,h-10),3,3);if(bar>0)d.DrawRoundedRectangle(AtlasPalette.Brush(Mode==1?"#55CBA4":"#B092EB"),null,new Rect(x,h-bar,7,bar),3,3);string label=new[]{"L","M","M","J","V","S","D"}[i];var txt=new FormattedText(label,System.Globalization.CultureInfo.GetCultureInfo("fr-FR"),FlowDirection.LeftToRight,new Typeface("Segoe UI"),9,Visuals.Muted);d.DrawText(txt,new Point(x-1,h+8));if(values[i]>0){var value=new FormattedText((Mode==2?(values[i]/3600.0).ToString("0.0"):values[i].ToString()),System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),8,Visuals.Text);d.DrawText(value,new Point(x-1,Math.Max(0,h-bar-13)));}}
        }
    }
