        void SetStudioCountry(MapCountry c){bool before=choosingCity;choosingCity=true;atlasCountries.SelectedItem=c;choosingCity=before;if(countryDisclosure!=null)countryDisclosure.Content=(c==null?"Choisir un pays":c.name)+"  ⌄";RefreshCityList();}
        void RefreshCityList(){if(atlasCities==null||atlas==null)return;bool before=choosingCity;choosingCity=true;atlasCities.ItemsSource=AtlasPlaces.Data.cities.Where(c=>c==atlas.City||(atlas.Selected==null?c.rank<=1:c.country==atlas.Selected.id)).OrderBy(c=>c.name).ToList();atlasCities.SelectedItem=atlas.City;choosingCity=before;}
        internal void PrepareVpnCity(){if(atlas==null||atlas.City==null){SetFootnote("Choisissez une ville.");return;}preferences.VpnCityId=atlas.City.id;RememberVpnCity(atlas.City.id);if(!SavePreferences())return;cityStatus.Text="Destination prête · VPN non connecté";RefreshRecents();SetFootnote(atlas.City.name+" enregistrée. Le fournisseur VPN reste à connecter.");}
        void RefreshRecents(){if(recentStrip==null)return;recentStrip.Children.Clear();var ids=preferences.RecentVpnCities.Take(5).ToList();foreach(string country in new[]{"FRA","USA","GBR","CAN","DEU"}){if(ids.Count>=5)break;if(ids.Any(id=>id.StartsWith(country+"-")))continue;var c=AtlasPlaces.Data.cities.Where(v=>v.country==country).OrderBy(v=>v.rank).ThenByDescending(v=>v.population).FirstOrDefault();if(c!=null)ids.Add(c.id);}foreach(string id in ids){var c=AtlasPlaces.Data.cities.FirstOrDefault(v=>v.id==id);if(c==null)continue;var n=AtlasData.Countries.FirstOrDefault(v=>v.id==c.country);var content=new StackPanel {Orientation=Orientation.Horizontal};content.Children.Add(new Viewbox {Width=50,Height=50,Child=new StudioFlag {Country=c.country},Margin=new Thickness(0,0,12,0)});var text=new StackPanel();text.Children.Add(Visuals.TextBlock(n==null?c.country:n.name,13,Visuals.Text));text.Children.Add(Visuals.TextBlock(preferences.RecentVpnCities.Contains(id)?c.name+" · préparée":"Explorer",10,Visuals.Muted));content.Children.Add(text);var b=StudioButton("",delegate {atlas.SelectCity(c,true);});b.Content=content;b.Padding=new Thickness(4);b.BorderThickness=new Thickness(0);b.Margin=new Thickness(0,0,26,10);b.ToolTip=preferences.RecentVpnCities.Contains(id)?"Destination préparée · aucun tunnel VPN":"Inspiration · aucune connexion passée";AutomationProperties.SetName(b,n==null?c.country:n.name);recentStrip.Children.Add(b);}}
        void UpdateStudio(){if(atlas==null||atlasYear==null)return;int era=Math.Min(6,(int)atlas.Position);string year=AtlasData.Year(atlas.Position).ToString();if(atlasYear.Text!=year)atlasYear.Text=year;if(studioTimeYear!=null)studioTimeYear.Text=year;atlasEra.Text=AtlasData.Names[era].ToUpperInvariant();atlasCopy.Text=atlas.City==null?"EXPLORER · LE TEMPS EST SUSPENDU":"MÉMOIRE LOCALE · VOTRE RYTHME";atlasPlay.Content=atlas.Playing?"Ⅱ  Suspendre":"▷  Temps local";atlasPlay.IsEnabled=atlas.City!=null&&atlas.Zoom>=5&&!preferences.ReducedMotion;updatingAtlas=true;atlasTimeline.Value=atlas.Position;updatingAtlas=false;timeCurve.InvalidateVisual();UpdateExplorer();}
        void UpdateExplorer(){if(atlas==null||studioStory==null)return;shownChapter=preferences.Premium?AtlasPlaces.Chapter(atlas.City,atlas.Selected,AtlasData.Year(atlas.Position)):null;string key=(atlas.City==null?atlas.Selected==null?"world":atlas.Selected.id:atlas.City.id)+"/"+(shownChapter==null?"none":shownChapter.title);if(key==lastStoryKey)return;lastStoryKey=key;studioFlag.Country=atlas.Selected==null?null:atlas.Selected.id;studioFlag.InvalidateVisual();studioLocation.Text=(atlas.City!=null?atlas.City.name+", "+(atlas.Selected==null?"Territoire":atlas.Selected.name):atlas.Selected!=null?atlas.Selected.name:"Monde");cityStatus.Text=atlas.City==null?"Choisissez une ville":"○  "+atlas.City.name+" · non connecté";if(shownChapter==null){studioStoryTitle.Text=atlas.City==null?"":atlas.City.name;studioStory.Text=atlas.City==null?"":"Une mémoire à composer.";}else {studioStoryTitle.Text=(shownChapter.kind=="world"?"Monde · ":"")+shownChapter.title;studioStory.Text=shownChapter.text.Split('.').First()+".  "+shownChapter.label;studioStory.ToolTip=shownChapter.text+"\nImage : "+shownChapter.imageCredit+"\n"+shownChapter.imageDescription+"\n"+shownChapter.imageSource;AutomationProperties.SetHelpText(studioStory,shownChapter.source);}if(!Visuals.ReducedMotion)Visuals.Fade(studioStoryTitle,0,1,650);}
        void RefreshStudioStats(){if(studioCounts==null)return;int total=HiddenCount("shorts")+HiddenCount("adult")+HiddenCount("ads");if(total!=lastStatsTotal){lastStatsTotal=total;studioCounts.Text=total+" éléments masqués";studioShorts.Text="◉ "+HiddenCount("shorts")+" flux";studioAds.Text="◇ "+HiddenCount("ads")+" pubs";studioAdult.Text="○ "+HiddenCount("adult")+" sensibles";studioSpark.InvalidateVisual();UpdateThreatPill();if(studioThreatGraph!=null)studioThreatGraph.InvalidateVisual();if(studioThreatCount!=null)studioThreatCount.Text=HiddenCount("malicious")+" sites d’hameçonnage bloqués";}UpdateThreatPill();if(studioThreatGraph!=null)studioThreatGraph.InvalidateVisual();if(studioThreatCount!=null)studioThreatCount.Text=HiddenCount("malicious")+" accès d’hameçonnage bloqués";if(studioThreatGraph!=null)studioThreatGraph.Visibility=ThreatRunning?Visibility.Visible:Visibility.Collapsed;if(studioThreatCount!=null)studioThreatCount.Visibility=ThreatRunning?Visibility.Visible:Visibility.Collapsed;studioApps.Text=preferences.Apps.Count(c=>c.Work)+" logiciels Travail · "+(Session.Active?"session active":"en veille");}
